<template>
  <div class="users">
    <OptimizationHeader
      title="Пользователи"
      status="Сейчас на странице"
      :count="totalCount"
    />
    <CustomMainHeader
      :showCreateButton="true"
      @create="goToCreateProfilePage"
      :sortOptions="[
        { label: 'Все', value: '0' },
        { label: 'Частные профили', value: '1' },
        { label: 'Коммерческие', value: '2' },
        { label: 'Заблокированные', value: '3' },
      ]"
    />
    <div class="users-table__box">
      <CustomTable
        :ItemRows="itemRow"
        :headerRows="headerRows"
        :lineClamp="5"
        height="120px"
        @slot-clicked="handleButtonClick"
        @item-clicked="handleArrowOptionClick"
        :tablePagination="false"
        :totalPages="totalPages"
      >
        <!-- Слот в начале строки -->
        <template #slot-start="{}">
          <CustomStatusIndicator status="green" title="В сети" />
        </template>
        <!-- Слот в конце строки -->
        <template #slot-end="{ item, emitEvent }">
          <CustomTableOption
            v-model="selectRole"
            :options="options"
            @update:model-value="handleOptionChange(item, emitEvent)"
          />
        </template>
      </CustomTable>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import CustomMainHeader from '@/components/UI/CustomMainHeader.vue';
import CustomTable from '@/components/UI/CustomTable.vue';
import CustomStatusIndicator from '@/components/UI/CustomStatusIndicator.vue';
import { getUsers } from '@/services/apiClient';
import CustomTableOption from '@/components/UI/CustomTableOption.vue';
import OptimizationHeader from '@/components/SEO/OptimizationHeader.vue';
import { useRouter } from 'vue-router';

const router = useRouter();

const options = [
  {
    name: 'Опубликовать от имени',
    code: 'publishAs',
    error: false,
    success: false,
    svg: 'publish-svg',
    ValidateType: 'select',
  },
  {
    name: 'Заблокировать',
    code: 'blockProfile',
    error: false,
    success: false,
    svg: 'block-svg',
    ValidateType: 'select',
  },
  {
    name: 'Копировать ссылку',
    code: 'copyLink',
    error: false,
    success: false,
    svg: 'copy-svg',
    ValidateType: 'select',
  },
  {
    name: 'Удалить профиль',
    code: 'deleteProfile',
    error: false,
    success: false,
    svg: 'delet-svg',
    ValidateType: 'select',
  },
];

const selectRole = ref({
  name: '',
  code: '',
  ValidateType: 'select',
  error: false,
  success: false,
});

const itemRow = ref([]);
const currentStep = ref(1);
const totalCount = ref(1);
const count = 50;
const orderBy = 'desc';

const headerRows = [
  { name: 'Статус', width: '70px', helper: false },
  { name: 'Имя', width: '150px', helper: false },
  { name: 'ID', width: '50px', helper: false },
  { name: 'Профиль', width: '100px', helper: false },
  { name: 'Телефон', width: '200px', helper: false },
  { name: 'E-mail', width: '200px', helper: false },
  {
    name: 'Объяв. (O|C|A)',
    width: '150px',
    helper: {
      title: 'Статусы объявлений',
      text: `Через разделитель перечислено количество объявлений в разных статусах: 
      “О” - опубликованные 
      ”С” -  снятые с публикации 
      “А” - перемещенные в архив.`,
    },
  },
  {
    name: 'Воронки',
    width: '100px',
    helper: {
      title: 'Воронка продаж',
      text: 'Цифра демонстрирует на каком этапе воронки продаж находится пользователь. В скобках указан номер воронки.',
    },
  },
  { name: '', width: '50px', helper: false },
];

const handleButtonClick = (item) => {
  if (selectRole.value.name === 'Редактировать') {
    router.push(`/seo/sections/create/${item.id.value}`);
  }
};

const goToCreateProfilePage = () => {
  router.push(`/create-profile`);
};

const handleOptionChange = (item, emitEvent) => {
  if (selectRole.value.code === 'copyLink') {
    const profileLink = `${window.location.origin}/user/${item.id.value}`;
    navigator.clipboard
      .writeText(profileLink)
      .then(() => {
        console.log('Ссылка скопирована:', profileLink);
      })
      .catch((err) => {
        console.error('Ошибка копирования:', err);
      });
  }

  console.log('Изменение в опции:', selectRole, emitEvent);
};

const handleArrowOptionClick = (item) => {
  router.push(`/user/${item.id.value}`);
};

const fetchUsers = async () => {
  try {
    const response = await getUsers({
      count,
      step: currentStep.value,
      order_by: orderBy,
    });

    const users = response.users || [];

    itemRow.value = users.map((user) => ({
      customOptionStart: { slot: 'start', contenteditable: false },
      name: {
        value: user.username || '—',
        type: 'text',
        contenteditable: false,
      },
      id: { value: user.id.toString(), type: 'text', contenteditable: false },
      profile: { value: '—', type: 'text', contenteditable: false },
      phone: { value: user.phone || '—', type: 'text', contenteditable: false },
      email: { value: user.email || '—', type: 'text', contenteditable: false },
      ads: { value: '—', type: 'text', contenteditable: false },
      funnel: { value: '—', type: 'text', contenteditable: false },
      customOptionEnd: { slot: 'end', contenteditable: false, id: user.id },
    }));

    totalCount.value = response.total_count;
  } catch (error) {
    console.error('Ошибка при загрузке пользователей', error);
  }
};

onMounted(async () => {
  await fetchUsers();
});
</script>

